"use client"
import * as React from "react"
import gsap from "gsap"
import { MotionPathPlugin } from "gsap/MotionPathPlugin"
import { useGSAP } from "@gsap/react"
import { MailCheck, RotateCw } from "lucide-react"
import { cn } from "@/lib/utils"

gsap.registerPlugin(useGSAP, MotionPathPlugin)

export interface EnvelopeSubscribeProps {
  title?: string
  description?: string
  /** Resolve when the address is accepted, reject to show the error state. */
  onSubscribe?: (email: string) => Promise<void>
  /** Called when the visitor asks for the message again. */
  onResend?: (email: string) => Promise<void>
  /** Seconds before "send again" unlocks. Default 30. */
  resendSeconds?: number
  className?: string
}

type Phase = "idle" | "sending" | "sent" | "error"
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/
const PAD = 160 // canvas margin around the card, so particles can leave it
const COLORS = ["#6c5cff", "#8b7bff", "#22d3ee", "#ff6b6b", "#ffffff"]
const GRADIENT = "linear-gradient(110deg,#5a49f0 0%,#7c5cff 35%,#ff6b6b 70%,#5a49f0 100%)"

interface P { x: number; y: number; vx: number; vy: number; life: number; max: number; r: number; c: string }

export function EnvelopeSubscribe({
  title = "Get the Friday letter",
  description = "One short email a week. Leave whenever you like.",
  onSubscribe, onResend, resendSeconds = 30, className,
}: EnvelopeSubscribeProps) {
  const uid = React.useId()
  const root = React.useRef<HTMLDivElement>(null)
  const card = React.useRef<HTMLFormElement>(null)
  const wrap = React.useRef<HTMLDivElement>(null)
  const btn = React.useRef<HTMLButtonElement>(null)
  const cv = React.useRef<HTMLCanvasElement>(null)
  const parts = React.useRef<P[]>([])
  const raf = React.useRef(0)
  const alive = React.useRef(true)
  const bob = React.useRef<gsap.core.Tween | null>(null)
  const [email, setEmail] = React.useState("")
  const [phase, setPhase] = React.useState<Phase>("idle")
  const [msg, setMsg] = React.useState("")
  const [left, setLeft] = React.useState(0)
  const [resending, setResending] = React.useState(false)
  const still = () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches

  React.useEffect(() => { alive.current = true; return () => { alive.current = false; cancelAnimationFrame(raf.current) } }, [])
  React.useEffect(() => {
    if (left <= 0) return
    const id = setTimeout(() => setLeft((n) => n - 1), 1000)
    return () => clearTimeout(id)
  }, [left])

  const { contextSafe } = useGSAP({ scope: root })

  /* ---------- tiny canvas particle engine (additive glow) ---------- */
  const loop = () => {
    const c = cv.current; if (!c) return
    const g = c.getContext("2d")!
    const dpr = window.devicePixelRatio || 1
    g.setTransform(dpr, 0, 0, dpr, 0, 0)
    g.clearRect(0, 0, c.width, c.height)
    g.globalCompositeOperation = "lighter"
    parts.current = parts.current.filter((p) => p.life < p.max)
    for (const p of parts.current) {
      p.life++; p.vy += 0.045; p.vx *= 0.985; p.vy *= 0.985; p.x += p.vx; p.y += p.vy
      const t = 1 - p.life / p.max
      g.globalAlpha = Math.max(0, t) * 0.9
      const grd = g.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 3.2)
      grd.addColorStop(0, p.c); grd.addColorStop(1, "transparent")
      g.fillStyle = grd; g.beginPath(); g.arc(p.x, p.y, p.r * 3.2 * (0.4 + t * 0.6), 0, 6.283); g.fill()
    }
    raf.current = parts.current.length ? requestAnimationFrame(loop) : 0
  }
  const spawn = (x: number, y: number, n: number, speed: number, spread = 6.283, dir = 0) => {
    for (let i = 0; i < n; i++) {
      const a = dir + (Math.random() - 0.5) * spread, s = speed * (0.3 + Math.random())
      parts.current.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: 0, max: 30 + Math.random() * 40, r: 1.2 + Math.random() * 2.2, c: COLORS[(Math.random() * COLORS.length) | 0] })
    }
    if (!raf.current) raf.current = requestAnimationFrame(loop)
  }
  const centerOf = (el: Element) => {
    const r = el.getBoundingClientRect(), c = cv.current!.getBoundingClientRect()
    return { x: r.left + r.width / 2 - c.left, y: r.top + r.height / 2 - c.top }
  }
  React.useEffect(() => {
    const c = cv.current, k = card.current; if (!c || !k) return
    const size = () => {
      const dpr = window.devicePixelRatio || 1
      const w = k.offsetWidth + PAD * 2, h = k.offsetHeight + PAD * 2
      c.width = w * dpr; c.height = h * dpr; c.style.width = w + "px"; c.style.height = h + "px"
    }
    size(); const ro = new ResizeObserver(size); ro.observe(k); return () => ro.disconnect()
  }, [])

  /* ---------- ambient motion: tilt, parallax, cursor light, breathing halo ---------- */
  useGSAP(() => {
    if (still()) return
    const k = card.current!
    const rx = gsap.quickTo(k, "rotationX", { duration: 0.6, ease: "power3.out" })
    const ry = gsap.quickTo(k, "rotationY", { duration: 0.6, ease: "power3.out" })
    const bx = gsap.quickTo(".es-blob-a", "x", { duration: 1.1, ease: "power3.out" })
    const by = gsap.quickTo(".es-blob-a", "y", { duration: 1.1, ease: "power3.out" })
    const cx = gsap.quickTo(".es-blob-b", "x", { duration: 1.6, ease: "power3.out" })
    const cy = gsap.quickTo(".es-blob-b", "y", { duration: 1.6, ease: "power3.out" })
    gsap.set(k, { transformPerspective: 900 })
    const move = (e: PointerEvent) => {
      const r = k.getBoundingClientRect()
      const px = (e.clientX - r.left) / r.width - 0.5, py = (e.clientY - r.top) / r.height - 0.5
      ry(px * 9); rx(-py * 9); bx(px * -34); by(py * -34); cx(px * 52); cy(py * 52)
      k.style.setProperty("--mx", `${e.clientX - r.left}px`); k.style.setProperty("--my", `${e.clientY - r.top}px`)
    }
    const leave = () => { ry(0); rx(0); bx(0); by(0); cx(0); cy(0) }
    k.addEventListener("pointermove", move); k.addEventListener("pointerleave", leave)
    gsap.to(".es-halo", { opacity: 0.85, scale: 1.035, duration: 2.2, ease: "sine.inOut", yoyo: true, repeat: -1 })
    gsap.to(btn.current, { backgroundPosition: "200% 0", duration: 5, ease: "none", repeat: -1 })
    return () => { k.removeEventListener("pointermove", move); k.removeEventListener("pointerleave", leave) }
  }, { scope: root })

  /* ---------- step 1: button melts into a seal, envelope draws itself ---------- */
  const toEnvelope = contextSafe(() => {
    const b = btn.current!, fast = still()
    gsap.set(b, { width: b.offsetWidth })
    gsap.killTweensOf(b, "backgroundPosition")
    const tl = gsap.timeline()
    tl.to(".es-label", { opacity: 0, y: fast ? 0 : -8, duration: 0.15 })
    if (fast) tl.set(b, { width: 56 }).to(".es-env", { opacity: 1, duration: 0.2 })
    else tl.to(b, { width: 56, duration: 0.55, ease: "elastic.out(1,0.7)" }, 0.05)
      .set(".es-env", { opacity: 1 }, 0.3)
      .fromTo(".es-env .draw", { strokeDashoffset: 1 }, { strokeDashoffset: 0, duration: 0.6, ease: "power2.out", stagger: 0.12 }, 0.3)
      .fromTo(".es-flap", { scaleY: 1 }, { scaleY: -1, svgOrigin: "12 7", duration: 0.35, ease: "back.out(2)" }, 0.75)
    if (!fast) bob.current = gsap.to(".es-env", { y: -2.5, rotation: 3, duration: 0.55, ease: "sine.inOut", yoyo: true, repeat: -1, delay: 1.2 })
    gsap.to(".es-field", { opacity: 0.5, duration: 0.25 })
    return tl
  })

  /* ---------- step 2: fold, launch on a curve with a particle trail, flash, check ---------- */
  const toDone = contextSafe(() => {
    bob.current?.kill()
    const fast = still(), tl = gsap.timeline()
    const checkIn = () => tl
      .set(".es-check", { opacity: 1 })
      .fromTo(".es-check path", { strokeDashoffset: 1 }, { strokeDashoffset: 0, duration: 0.5, ease: "power3.out", immediateRender: false })
    if (fast) {
      tl.to(".es-env", { opacity: 0, duration: 0.15 }); checkIn()
    } else {
      const k = card.current!
      tl.to(".es-env", { y: 0, rotation: 0, duration: 0.1 })
        .to(".es-flap", { scaleY: 1, svgOrigin: "12 7", duration: 0.25, ease: "power2.in" })
        .to(".es-env", { scaleX: 0.62, scaleY: 0.82, duration: 0.22, ease: "power2.inOut" }) // fold
        .to(".es-env", { scale: 1.25, duration: 0.14, ease: "power2.out" })
        .set(".es-env", { opacity: 0 })
        .set(".es-fly", { opacity: 1, x: 0, y: 0, rotation: -20, scale: 1 })
        .to(".es-fly", {
          duration: 1.15, ease: "power2.inOut",
          motionPath: { path: [{ x: 0, y: 0 }, { x: -70, y: -90 }, { x: 40, y: -210 }, { x: 150, y: -250 }], curviness: 1.6, autoRotate: 90 },
          scale: 0.45,
          onUpdate() { const c = centerOf(document.querySelector(".es-fly")!); spawn(c.x, c.y, 3, 1.1) },
        })
        .to(".es-fly svg", { rotation: 360, duration: 1.15, ease: "power1.in", transformOrigin: "50% 50%" }, "<")
        .set(".es-fly", { opacity: 0 })
        .add(() => { const c = centerOf(document.querySelector(".es-fly")!); spawn(c.x, c.y, 70, 4.6); spawn(c.x, c.y, 24, 2) })
        .fromTo(".es-flash", { opacity: 0.95, scale: 0.2 }, { opacity: 0, scale: 1.6, duration: 0.7, ease: "power2.out", immediateRender: false }, "<")
        .fromTo(k, { y: 0 }, { y: -4, duration: 0.09, yoyo: true, repeat: 1, ease: "power1.inOut", immediateRender: false }, "<")
        .to(".es-halo", { opacity: 1, scale: 1.08, duration: 0.25, yoyo: true, repeat: 1 }, "<")
      checkIn()
      tl.add(() => { const c = centerOf(btn.current!); spawn(c.x, c.y, 36, 3.2) }, "<0.1")
        .fromTo(btn.current, { scale: 1 }, { scale: 1.14, duration: 0.15, yoyo: true, repeat: 1, ease: "power1.inOut" }, "<")
        .fromTo(".es-ring", { scale: 1, opacity: 0.7 }, { scale: 2.6, opacity: 0, duration: 0.9, stagger: 0.16, ease: "power2.out", immediateRender: false }, "<")
    }
    tl.fromTo(".es-panel", { height: 0, opacity: 0 }, { height: "auto", opacity: 1, duration: fast ? 0.2 : 0.55, ease: "power3.out" }, fast ? 0 : "-=0.5")
    return tl
  })

  const toIdle = contextSafe((withShake: boolean) => {
    bob.current?.kill()
    const fast = still()
    const tl = gsap.timeline({
      onComplete: () => {
        gsap.set(btn.current, { clearProps: "width,scale" })
        gsap.set(".es-env,.es-check,.es-label,.es-field,.es-fly", { clearProps: "all" })
        gsap.set(".es-env .draw,.es-check path", { strokeDashoffset: 1 })
        if (!fast) gsap.to(btn.current, { backgroundPosition: "200% 0", duration: 5, ease: "none", repeat: -1 })
      },
    })
    tl.to(".es-env,.es-check", { opacity: 0, duration: 0.15 })
      .to(".es-panel", { height: 0, opacity: 0, duration: fast ? 0.01 : 0.3 }, 0)
      .to(btn.current, { width: wrap.current!.offsetWidth, duration: fast ? 0.01 : 0.5, ease: "elastic.out(1,0.8)" }, 0.1)
      .to(".es-label", { opacity: 1, y: 0, duration: 0.2 }, fast ? 0 : 0.4)
    if (withShake && !fast) tl.fromTo(wrap.current, { x: 0 }, { keyframes: { x: [-9, 9, -6, 6, 0] }, duration: 0.45 }, 0.1)
    return tl
  })

  const shakeField = contextSafe(() => { if (!still()) gsap.fromTo(".es-field", { x: 0 }, { keyframes: { x: [-9, 9, -6, 6, 0] }, duration: 0.45 }) })

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (phase === "sending" || phase === "sent") return
    if (!EMAIL.test(email.trim())) { setMsg(email.trim() ? "That doesn't look like an email yet." : "Add your email first."); shakeField(); return }
    setMsg(""); setPhase("sending")
    const intro = toEnvelope()
    try {
      await onSubscribe?.(email.trim())
      await intro
      if (!alive.current) return
      setPhase("sent"); setLeft(resendSeconds); toDone()
    } catch {
      await intro
      if (!alive.current) return
      setPhase("error"); setMsg("We couldn't reach the server. Your address is still here, try again."); toIdle(true)
    }
  }
  const resend = async () => {
    if (left > 0 || resending) return
    setResending(true)
    try { await onResend?.(email.trim()); setLeft(resendSeconds) } finally { if (alive.current) setResending(false) }
  }
  const reset = () => { setPhase("idle"); setLeft(0); toIdle(false) }
  const sent = phase === "sent"

  return (
    <div ref={root} className={cn("relative w-full max-w-sm", className)} style={{ perspective: 1000 }}>
      <div aria-hidden className="es-halo pointer-events-none absolute -inset-3 rounded-[2rem] bg-[conic-gradient(from_200deg,#6c5cff,#22d3ee,#ff6b6b,#6c5cff)] opacity-40 blur-2xl dark:opacity-55" />
      <form ref={card} onSubmit={submit} noValidate aria-label={title}
        className="relative rounded-2xl border border-border bg-card p-6 text-foreground shadow-[0_30px_60px_-30px_rgba(40,30,120,0.45)]"
        style={{ ["--mx" as string]: "50%", ["--my" as string]: "0%", transformStyle: "preserve-3d" }}>
        <div aria-hidden className="pointer-events-none absolute inset-0 overflow-hidden rounded-2xl">
          <div className="es-blob-a absolute -left-10 -top-16 size-44 rounded-full bg-[#6c5cff]/25 blur-3xl" />
          <div className="es-blob-b absolute -bottom-16 -right-8 size-40 rounded-full bg-[#ff6b6b]/20 blur-3xl" />
          <div className="absolute inset-0" style={{ background: "radial-gradient(220px circle at var(--mx) var(--my), color-mix(in oklab, var(--primary) 16%, transparent), transparent 70%)" }} />
        </div>
        <div aria-hidden className="es-flash pointer-events-none absolute left-1/2 top-1/2 size-[28rem] -translate-x-1/2 -translate-y-1/2 rounded-full bg-[radial-gradient(circle,#ffffff_0%,#9c8fff_25%,transparent_65%)] opacity-0 mix-blend-plus-lighter" />

        <div className="relative" style={{ transform: "translateZ(30px)" }}>
          <h2 className="text-lg font-semibold leading-tight">{title}</h2>
          <p className="mt-1 text-sm text-muted-foreground">{description}</p>

          <div className="es-field mt-5">
            <label htmlFor={`${uid}-e`} className="mb-1.5 block text-sm font-medium">Email</label>
            <input id={`${uid}-e`} type="email" autoComplete="email" inputMode="email" placeholder="you@example.com" value={email}
              readOnly={phase === "sending" || sent} aria-invalid={!!msg && !sent} aria-describedby={`${uid}-m`}
              onChange={(e) => { setEmail(e.target.value); if (msg) setMsg("") }}
              className="block min-h-11 w-full rounded-xl border border-border bg-background px-3 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus:border-primary focus:shadow-[0_0_0_4px_color-mix(in_oklab,var(--primary)_22%,transparent)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring" />
            <p id={`${uid}-m`} role={msg ? "alert" : undefined} className="mt-1.5 min-h-4 text-xs text-red-700 dark:text-red-300">{msg}</p>
          </div>

          <div ref={wrap} className="relative mt-2 flex justify-center">
            <button ref={btn} type="submit" disabled={phase === "sending"} aria-busy={phase === "sending"}
              aria-label={sent ? "Subscribed" : phase === "sending" ? "Sending your request" : "Subscribe"}
              style={{ background: GRADIENT, backgroundSize: "250% 100%" }}
              className="relative grid h-14 min-h-11 w-full place-items-center rounded-[28px] text-sm font-semibold text-white shadow-[0_10px_30px_-8px_rgba(108,92,255,0.7)] outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring">
              <span className="es-label">Subscribe</span>
              <svg className="es-env pointer-events-none absolute opacity-0" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                <rect className="draw" x="3" y="7" width="18" height="12" rx="2.2" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
                <polyline className="es-flap draw" points="3.4,7.6 12,13.6 20.6,7.6" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
              </svg>
              <svg className="es-check pointer-events-none absolute opacity-0" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                <path d="M6 12.5l4 4 8-9" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
              </svg>
              {[0, 1].map((i) => <span key={i} aria-hidden className="es-ring pointer-events-none absolute size-14 rounded-full border-2 border-[#8b7bff] opacity-0" />)}
            </button>
            <span aria-hidden className="es-fly pointer-events-none absolute left-1/2 top-1/2 -ml-4 -mt-4 opacity-0">
              <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" style={{ filter: "drop-shadow(0 0 8px #8b7bff)" }}>
                <rect x="3" y="7" width="18" height="12" rx="2.2" fill="#6c5cff" /><polyline points="3.4,7.6 12,13.6 20.6,7.6" />
              </svg>
            </span>
          </div>

          <div className="es-panel overflow-hidden opacity-0" style={{ height: 0 }} aria-live="polite" role="status">
            {sent && (
              <div className="mt-5 rounded-xl border border-border bg-muted/70 p-4">
                <p className="flex items-center gap-2 text-sm font-medium"><MailCheck className="size-4 text-primary dark:text-[color-mix(in_oklab,var(--primary),white_45%)]" aria-hidden /> Check your inbox</p>
                <p className="mt-1 text-sm text-muted-foreground">We sent a link to <span className="font-medium text-foreground">{email}</span>. Open it to finish. It can take a minute, and the spam folder is worth a look.</p>
                <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1">
                  <button type="button" onClick={resend} disabled={left > 0 || resending}
                    className="inline-flex min-h-11 items-center gap-1.5 rounded-lg text-sm font-medium text-primary outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:text-muted-foreground dark:text-[color-mix(in_oklab,var(--primary),white_45%)] dark:disabled:text-muted-foreground">
                    {left > 0 ? <><svg viewBox="0 0 16 16" className="size-4 -rotate-90" aria-hidden><circle cx="8" cy="8" r="6" fill="none" strokeWidth="2" className="stroke-border" /><circle cx="8" cy="8" r="6" fill="none" strokeWidth="2" stroke="currentColor" strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - left / resendSeconds} className="transition-[stroke-dashoffset] duration-1000 ease-linear" /></svg>Send again in {left}s</>
                      : resending ? <><RotateCw className="size-4 animate-spin motion-reduce:animate-none" aria-hidden />Sending</> : <><RotateCw className="size-4" aria-hidden />Send it again</>}
                  </button>
                  <button type="button" onClick={reset} className="inline-flex min-h-11 items-center rounded-lg text-sm text-muted-foreground underline-offset-4 outline-none hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring">Wrong address?</button>
                </div>
              </div>
            )}
          </div>
          <p className="mt-4 text-xs text-muted-foreground">No spam. One click to unsubscribe.</p>
        </div>
      </form>
      <canvas ref={cv} aria-hidden className="pointer-events-none absolute z-10" style={{ left: -PAD, top: -PAD }} />
    </div>
  )
}

export default function Demo() {
  return <EnvelopeSubscribe resendSeconds={6} onSubscribe={() => new Promise((r) => setTimeout(r, 1500))} onResend={() => new Promise((r) => setTimeout(r, 700))} />
}

